from flask import Flask

app = Flask(__name__)

HTML_PAGE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>TIMO TRADING PRO - Private</title>
<script src="https://cdn.tailwindcss.com"></script>
</head>
<body style="background:#0e0e10;color:#fff;font-family:Inter,sans-serif" class="overflow-hidden">
<div class="flex justify-between items-center px-4 py-2 bg-black border-b border-gray-800">
<div class="flex items-center gap-3"><span class="font-bold text-lg">TIMO TRADING PRO</span><span class="text-xs bg-yellow-500 text-black px-2 py-1 rounded">PRIVATE MODE</span></div>
<div class="flex items-center gap-2"><span class="text-sm text-gray-400">Balance:</span><span id="balance" class="font-bold text-green-400 text-lg">$12.14</span><button onclick="openModal('deposit')" class="bg-blue-600 px-3 py-1 rounded text-sm">Deposit</button><button onclick="openModal('withdraw')" class="bg-gray-700 px-3 py-1 rounded text-sm">Withdraw</button></div>
</div>
<div class="flex h-[calc(100vh-48px)]">
<div class="w-[170px] bg-[#151515] border-r border-gray-800 overflow-y-auto"><div class="p-2 text-[11px] text-gray-500 uppercase">Forex - Real Live</div><div id="forexList"></div><div class="p-2 text-[11px] text-gray-500 uppercase mt-2">Commodities</div><div id="commodityList"></div><div class="p-2 text-[11px] text-gray-500 uppercase mt-2">Indices</div><div id="indicesList"></div><div class="p-2 text-[11px] text-gray-500 uppercase mt-2">Crypto</div><div id="cryptoList"></div></div>
<div class="flex-1 flex flex-col bg-[#0e0e10]"><div class="flex justify-between items-center px-3 py-2 bg-[#1a1a1a] border-b border-gray-800 text-xs"><div class="flex items-center gap-3"><span id="currentSymbol" class="font-bold text-sm">EURUSD</span><span id="currentPrice" class="text-green-400">1.08452</span><span class="text-gray-500">Real Live</span></div><button onclick="runAIScanner()" class="bg-gradient-to-r from-purple-600 to-blue-600 px-3 py-1 rounded font-bold text-xs animate-pulse">🤖 AI SCANNER</button></div><div id="tradingview_widget" class="flex-1"></div><div id="aiResult" class="hidden p-2 bg-purple-900/30 border-t border-purple-700 text-xs"></div></div>
<div class="w-[260px] bg-[#151515] border-l border-gray-800 p-3 flex flex-col"><div class="flex gap-2 mb-3"><button id="modeForex" onclick="setMode('forex')" class="flex-1 py-2 bg-white text-black rounded font-bold text-xs">FOREX & GOLD</button><button id="modeOption" onclick="setMode('option')" class="flex-1 py-2 bg-[#2a2a2a] rounded font-bold text-xs">OPTIONS</button></div><div id="forexPanel"><label class="text-[11px] text-gray-400">Lot Size</label><input id="lotSize" type="number" value="1.00" class="w-full bg-black border border-gray-700 rounded p-2 mt-1 mb-3 text-sm"><div class="flex gap-2 mb-3"><button onclick="placeTrade('buy')" class="flex-1 bg-[#00c176] py-3 rounded font-bold">BUY</button><button onclick="placeTrade('sell')" class="flex-1 bg-[#ff3b30] py-3 rounded font-bold">SELL</button></div></div><div id="optionPanel" class="hidden"><label class="text-[11px] text-gray-400">Option Amount</label><input id="optAmount" type="number" value="5" class="w-full bg-black border border-gray-700 rounded p-2 mt-1 mb-2 text-sm"><label class="text-[11px] text-gray-400">Expiry</label><select id="optExpiry" class="w-full bg-black border border-gray-700 rounded p-2 mt-1 mb-3 text-sm"><option value="1">1 min - Turbo</option><option value="3" selected>3 min</option><option value="5">5 min</option><option value="15">15 min - Classic</option><option value="60">1 hour</option></select><div class="flex gap-2 mb-2"><button onclick="placeOption('call')" class="flex-1 bg-[#00c176] py-3 rounded font-bold">CALL ▲</button><button onclick="placeOption('put')" class="flex-1 bg-[#ff3b30] py-3 rounded font-bold">PUT ▼</button></div></div><button onclick="closeAllTrades()" class="mt-2 w-full bg-gray-800 py-2 rounded text-xs border border-gray-700">CLOSE ALL NOW</button><div class="mt-4 border-t border-gray-800 pt-3"><p class="text-[11px] text-gray-400 mb-2">Open Trades (<span id="tradeCount">0</span>)</p><div id="openTrades" class="space-y-2 max-h-[300px] overflow-y-auto text-[11px]"></div></div></div>
</div>
<div id="depositModal" class="hidden fixed inset-0 bg-black/80 flex items-center justify-center z-50"><div class="bg-[#1e1e1e] p-5 rounded w-[320px] border border-gray-700"><h3 class="font-bold mb-3">Deposit (Private)</h3><input id="depositAmount" type="number" placeholder="100" class="w-full bg-black border border-gray-700 rounded p-2 mb-3"><div class="flex gap-2"><button onclick="doDeposit()" class="flex-1 bg-blue-600 py-2 rounded">Add</button><button onclick="closeModal('deposit')" class="flex-1 bg-gray-700 py-2 rounded">Cancel</button></div></div></div>
<div id="withdrawModal" class="hidden fixed inset-0 bg-black/80 flex items-center justify-center z-50"><div class="bg-[#1e1e1e] p-5 rounded w-[320px] border border-gray-700"><h3 class="font-bold mb-3">Withdraw</h3><input id="withdrawAmount" type="number" placeholder="Amount" class="w-full bg-black border border-gray-700 rounded p-2 mb-3"><div class="flex gap-2"><button onclick="doWithdraw()" class="flex-1 bg-green-600 py-2 rounded">Withdraw</button><button onclick="closeModal('withdraw')" class="flex-1 bg-gray-700 py-2 rounded">Cancel</button></div></div></div>
<script src="https://s3.tradingview.com/tv.js"></script>
<script>
let balance=parseFloat(localStorage.getItem('timo_balance')||'12.14');let trades=JSON.parse(localStorage.getItem('timo_trades')||'[]');let currentSymbolTV='FX:EURUSD';let currentSymbolShort='EURUSD';let mode='forex';
const markets={forex:[{id:'EURUSD',tv:'FX:EURUSD',name:'EUR/USD'},{id:'GBPUSD',tv:'FX:GBPUSD',name:'GBP/USD'},{id:'USDJPY',tv:'FX:USDJPY',name:'USD/JPY'},{id:'AUDUSD',tv:'FX:AUDUSD',name:'AUD/USD'},{id:'USDCAD',tv:'FX:USDCAD',name:'USD/CAD'}],commodity:[{id:'GOLD',tv:'OANDA:XAUUSD',name:'Gold'},{id:'SILVER',tv:'OANDA:XAGUSD',name:'Silver'},{id:'OIL',tv:'TVC:USOIL',name:'Oil'}],indices:[{id:'US30',tv:'OANDA:US30USD',name:'US30'},{id:'NAS100',tv:'OANDA:NAS100USD',name:'NAS100'},{id:'SPX500',tv:'OANDA:SPX500USD',name:'SPX500'}],crypto:[{id:'BTCUSD',tv:'BINANCE:BTCUSDT',name:'BTC/USD'},{id:'ETHUSD',tv:'BINANCE:ETHUSDT',name:'ETH/USD'},{id:'SOLUSD',tv:'BINANCE:SOLUSDT',name:'SOL/USD'}]};
function renderLists(){const make=(arr,container)=>{const el=document.getElementById(container);el.innerHTML=arr.map(m=>`<div onclick="selectSymbol('${m.tv}','${m.id}')" class="px-2 py-2 hover:bg-[#2a2a2a] cursor-pointer flex justify-between text-xs border-b border-[#1f1f1f]"><span>${m.name}</span><span class="text-green-400">● LIVE</span></div>`).join('');};make(markets.forex,'forexList');make(markets.commodity,'commodityList');make(markets.indices,'indicesList');make(markets.crypto,'cryptoList');}
function selectSymbol(tv,shortSym){currentSymbolTV=tv;currentSymbolShort=shortSym;document.getElementById('currentSymbol').innerText=shortSym;loadTV(tv);}
function loadTV(symbol){document.getElementById('tradingview_widget').innerHTML='';new TradingView.widget({autosize:true,symbol:symbol,interval:"1",timezone:"Africa/Nairobi",theme:"dark",style:"1",locale:"en",container_id:"tradingview_widget",backgroundColor:"#121212"});}
function setMode(m){mode=m;document.getElementById('modeForex').className=m==='forex'?'flex-1 py-2 bg-white text-black rounded font-bold text-xs':'flex-1 py-2 bg-[#2a2a2a] rounded font-bold text-xs';document.getElementById('modeOption').className=m==='option'?'flex-1 py-2 bg-white text-black rounded font-bold text-xs':'flex-1 py-2 bg-[#2a2a2a] rounded font-bold text-xs';document.getElementById('forexPanel').classList.toggle('hidden',m!=='forex');document.getElementById('optionPanel').classList.toggle('hidden',m!=='option');}
function updateBalance(){document.getElementById('balance').innerText='$'+balance.toFixed(2);localStorage.setItem('timo_balance',balance);}
function placeTrade(dir){const amt=parseFloat(document.getElementById('lotSize').value||'1');if(balance<amt*0.1){alert('Low balance');return;}balance-=amt*0.1;const t={id:Date.now(),symbol:currentSymbolShort,type:'FOREX '+dir.toUpperCase(),amount:amt,dir,profit:(Math.random()*4-1).toFixed(2),time:new Date().toLocaleTimeString()};trades.push(t);saveTrades();updateBalance();renderTrades();}
function placeOption(dir){const amt=parseFloat(document.getElementById('optAmount').value||'5');const exp=document.getElementById('optExpiry').value;if(balance<amt){alert('Low balance');return;}balance-=amt;const t={id:Date.now(),symbol:currentSymbolShort,type:'OPTION '+dir.toUpperCase()+' '+exp+'m',amount:amt,dir,profit:'--',time:new Date().toLocaleTimeString(),expiry:Date.now()+parseInt(exp)*60000,payout:0.85};trades.push(t);saveTrades();updateBalance();renderTrades();setTimeout(()=>resolveOption(t.id),parseInt(exp)*60000);}
function resolveOption(id){const tr=trades.find(x=>x.id===id);if(!tr)return;const win=Math.random()>0.4;tr.profit=win?(tr.amount*tr.payout).toFixed(2):(-tr.amount).toFixed(2);if(win)balance+=tr.amount+parseFloat(tr.profit);updateBalance();saveTrades();renderTrades();}
function renderTrades(){document.getElementById('tradeCount').innerText=trades.length;const c=document.getElementById('openTrades');if(trades.length===0){c.innerHTML='<p class="text-gray-600">No open trades</p>';return;}c.innerHTML=trades.slice().reverse().map(tr=>{const pnl=tr.profit==='--'?'<span class="text-yellow-400">RUNNING</span>':`<span class="${parseFloat(tr.profit)>=0?'text-green-400':'text-red-400'}">${tr.profit>0?'+':''}$${tr.profit}</span>`;return `<div class="bg-black border border-gray-800 p-2 rounded flex justify-between"><div><div class="font-bold">${tr.symbol} ${tr.type}</div><div class="text-gray-500">${tr.time} $${tr.amount}</div></div><div class="text-right">${pnl}<br><button onclick="closeTrade(${tr.id})" class="text-[10px] bg-gray-800 px-2 py-1 rounded mt-1">CLOSE</button></div></div>`;}).join('');}
function closeTrade(id){const idx=trades.findIndex(x=>x.id===id);if(idx>-1){const tr=trades[idx];if(tr.profit==='--')balance+=tr.amount*0.5;updateBalance();trades.splice(idx,1);saveTrades();renderTrades();}}
function closeAllTrades(){if(!confirm('Close all?'))return;trades.forEach(tr=>{if(tr.profit==='--')balance+=tr.amount*0.5;});trades=[];saveTrades();updateBalance();renderTrades();}
function saveTrades(){localStorage.setItem('timo_trades',JSON.stringify(trades));}
function runAIScanner(){const box=document.getElementById('aiResult');box.classList.remove('hidden');box.innerHTML='🤖 AI Scanner analyzing '+currentSymbolShort+'...';setTimeout(()=>{const signals=['STRONG BUY','STRONG SELL','BUY CALL - Best Market','BUY PUT - Best Market'];const pick=signals[Math.floor(Math.random()*signals.length)];const conf=(70+Math.random()*25).toFixed(1);box.innerHTML=`✅ AI: <b class="text-green-400">${pick}</b> (${conf}% conf)<br>Best market: ${currentSymbolShort}<br>Auto-executing...`;setTimeout(()=>{if(pick.includes('BUY')||pick.includes('CALL')){if(mode==='forex')placeTrade('buy');else placeOption('call');}else{if(mode==='forex')placeTrade('sell');else placeOption('put');}box.innerHTML+='<br>🚀 AI trade executed!';},1500);},2000);}
function openModal(m){document.getElementById(m+'Modal').classList.remove('hidden');}
function closeModal(m){document.getElementById(m+'Modal').classList.add('hidden');}
function doDeposit(){const amt=parseFloat(document.getElementById('depositAmount').value);if(!amt)return;balance+=amt;updateBalance();closeModal('deposit');}
function doWithdraw(){const amt=parseFloat(document.getElementById('withdrawAmount').value);if(!amt||amt>balance){alert('Insufficient');return;}balance-=amt;updateBalance();closeModal('withdraw');}
renderLists();loadTV(currentSymbolTV);updateBalance();renderTrades();
setInterval(()=>{document.getElementById('currentPrice').innerText=(Math.random()*2+1).toFixed(5);},1200);
</script>
</body>
</html>
"""

@app.route('/')
def home():
    return HTML_PAGE

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=10000)
